  "status": "SUPPORTED",
  "claim": {
    "component_id": "C063.component",
    "value": "Shifting deadlines alone must not count as improvement.",
    "scope": "Validity of improvement claims; the limitation concerns deadline shifts by themselves.",
    "provenance": {
      "refs": [
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited span explicitly supplies this limitation."
    }
  },
  "signal_basis": {
    "component_id": "C063.signal_basis",
    "value": "Reductions are tested with the agreed start deadline fixed, observing repeated lateness and its disappearance after specified further removals. Improvement is assessed against existing-service deadlines.",
    "scope": "The selected turnaround replay and the deadline standard for assessing the bounded field trial.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish the failure definition, fixed deadline during testing, observed reduction pattern, and existing-service deadlines for trial assessment."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C063.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed for this limitation."
    }
  },
  "rationale": "The mapping defines lateness against an agreed deadline and holds that standard fixed. Shifting the deadline alone changes the assessment threshold without demonstrating better performance against the existing-service deadline. The claimed exclusion is therefore warranted within its stated bounds.",
  "uncertainty": "The limitation does not decide whether a deadline change accompanied by operational changes could improve service.",
  "anomalies": []
}
